//! FreeRDP 3 backend for transom-view. All FFI (and all `unsafe`) lives here.
#![allow(unsafe_code)]

/// Raw bindings generated by bindgen at build time (ADR 0001).
#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    unsafe_op_in_unsafe_fn,
    missing_debug_implementations,
    clippy::all
)]
pub mod ffi {
    include!(concat!(env!("OUT_DIR"), "/freerdp_bindings.rs"));
}

mod cliprdr;
mod engine;

pub use engine::{FreeRdpEngine, h264_available};
